&lt;?xml version="1.0" encoding="UTF-8"?&gt;
&lt;project version="4"&gt;
  &lt;component name="MavenProjectsManager"&gt;
    &lt;option name="originalFiles" value="&#36;PROJECT_DIR&#36;/pom.xml" /&gt;
  &lt;/component&gt;
  &lt;component name="ProjectRunConfigurationManager"&gt;
    &lt;configuration default="false" name="LoginApp (Maven)" type="MavenRunConfiguration" factoryName="Maven"&gt;
      &lt;MavenSettings&gt;
        &lt;option name="myGeneralSettings" /&gt;
        &lt;option name="myRunnerSettings" /&gt;
        &lt;option name="myDokkaSettings" /&gt;
        &lt;option name="myMavenSettings" /&gt;
        &lt;option name="myRunnerParameters"&gt;
          &lt;MavenRunnerParameters&gt;
            &lt;option name="profiles"&gt;
              &lt;set /&gt;
            &lt;/option&gt;
            &lt;option name="goals"&gt;
              &lt;list&gt;
                &lt;string&gt;clean&lt;/string&gt;
                &lt;string&gt;javafx:run&lt;/string&gt;
              &lt;/list&gt;
            &lt;/option&gt;
            &lt;option name="pomFileName" value="" /&gt;
            &lt;option name="resolveToWorkspace" value="false" /&gt;
            &lt;option name="workingDirPath" value="&#36;PROJECT_DIR&#36;" /&gt;
          &lt;/MavenRunnerParameters&gt;
        &lt;/option&gt;
      &lt;/MavenSettings&gt;
      &lt;method v="2" /&gt;
    &lt;/configuration&gt;
    &lt;configuration default="false" name="LoginApp (Direct)" type="Application" factoryName="Application" nameIsGenerated="true"&gt;
      &lt;option name="MAIN_CLASS_NAME" value="tn.esprit.mains.LoginApp" /&gt;
      &lt;module name="untitled" /&gt;
      &lt;option name="VM_PARAMETERS" value="--add-modules javafx.controls,javafx.fxml" /&gt;
      &lt;method v="2"&gt;
        &lt;option name="Make" enabled="true" /&gt;
      &lt;/method&gt;
    &lt;/configuration&gt;
  &lt;/component&gt;
&lt;/project&gt;

@echo off REM Script to run the Sport Insight Application
echo Compiling and running Sport Insight... echo.
REM Clean and compile echo Step 1: Cleaning and compiling... call mvn clean compile
if %ERRORLEVEL% NEQ 0 ( echo Compilation failed! pause exit /b 1 )
REM Run the application using javafx-maven-plugin echo. echo Step 2: Running the application... call mvn javafx:run
pause

@echo off
REM Script de vérification du projet Sport Insight (Windows)

echo =========================================
echo   Sport Insight - Vérification du projet
echo =========================================
echo.

REM Vérifier Java
echo 1. Vérification de Java...
java -version >nul 2>&1
if %ERRORLEVEL% EQU 0 (
    for /f "tokens=*" %%i in ('java -version 2^>^&1 ^| findstr "version"') do set JAVA_VERSION=%%i
    echo    + Java trouvé: %JAVA_VERSION%
) else (
    echo    - Java non trouvé. Veuillez installer Java JDK 17+
    exit /b 1
)

REM Vérifier Maven
echo.
echo 2. Vérification de Maven...
mvn -v >nul 2>&1
if %ERRORLEVEL% EQU 0 (
    echo    + Maven trouvé
) else (
    echo    - Maven non trouvé. Veuillez installer Maven 3.8+
    exit /b 1
)

REM Vérifier la structure
echo.
echo 3. Vérification de la structure...
if exist "pom.xml" (
    echo    + pom.xml trouvé
) else (
    echo    - pom.xml non trouvé
    exit /b 1
)

if exist "src\main\java\module-info.java" (
    echo    + module-info.java trouvé
) else (
    echo    - module-info.java non trouvé
    exit /b 1
)

if exist "src\main\resources\views\login.fxml" (
    echo    + login.fxml trouvé
) else (
    echo    - login.fxml non trouvé
    exit /b 1
)

if exist "src\main\java\tn\esprit\mains\LoginApp.java" (
    echo    + LoginApp.java trouvé
) else (
    echo    - LoginApp.java non trouvé
    exit /b 1
)

REM Compiler
echo.
echo 4. Compilation du projet...
mvn clean compile

if %ERRORLEVEL% EQU 0 (
    echo    + Compilation réussie
) else (
    echo    - Erreur de compilation
    exit /b 1
)

echo.
echo =========================================
echo  + Toutes les vérifications sont passées!
echo =========================================
echo.
echo Pour lancer l'application:
echo   mvn javafx:run
echo.
pause
